"""Handwritten trusted-base fixtures: expected outputs are literal, not generated by cleaner/executor."""
import pandas as pd

def fixtures():
    return [
        {
            "name": "strip_whitespace",
            "input": pd.DataFrame({"city": [" Paris ", "Rome"]}),
            "rules": {"strip_strings": ["city"]},
            "expected": pd.DataFrame({"city": ["Paris", "Rome"]}),
            "invariant": "Only surrounding whitespace changes; row order and other values remain unchanged."
        },
        {
            "name": "sentinel_to_missing",
            "input": pd.DataFrame({"score": [10, -999, 7]}),
            "rules": {"sentinel_map": {"score": [-999]}},
            "expected": pd.DataFrame({"score": [10, pd.NA, 7]}),
            "invariant": "Only explicitly declared sentinel values become missing."
        },
        {
            "name": "category_alias",
            "input": pd.DataFrame({"region": ["north", "NORTH", "south"]}),
            "rules": {"category_map": {"region": {"NORTH": "north"}}},
            "expected": pd.DataFrame({"region": ["north", "north", "south"]}),
            "invariant": "Only explicitly declared category aliases are normalized."
        },
        {
            "name": "numeric_coercion",
            "input": pd.DataFrame({"amount": ["10", "bad", "2.5"]}),
            "rules": {"numeric_coerce": ["amount"]},
            "expected": pd.DataFrame({"amount": [10.0, float("nan"), 2.5]}),
            "invariant": "Numeric strings parse; unparseable strings become missing rather than guessed values."
        },
        {
            "name": "strip_whitespace_mixed",
            "input": pd.DataFrame({"city": [" Tokyo", "Berlin  "]}),
            "rules": {"strip_strings": ["city"]},
            "expected": pd.DataFrame({"city": ["Tokyo", "Berlin"]}),
            "invariant": "Whitespace normalization is limited to explicitly selected string columns."
        },
        {
            "name": "deduplicate",
            "input": pd.DataFrame({"id": [1, 1, 2], "v": ["a", "a", "b"]}),
            "rules": {"drop_exact_duplicates": True},
            "expected": pd.DataFrame({"id": [1, 2], "v": ["a", "b"]}),
            "invariant": "Only exact duplicate rows are removed, preserving first occurrence."
        },
    ]
